import React from 'react';
import { Navigate, Outlet } from 'react-router-dom';
import Cookies from 'js-cookie';
import toast from 'react-hot-toast';

export const UserProtectedRoute = () => {
  const token = Cookies.get('token');
  const userInfo = Cookies.get('userInfo');

  // If there's no token or no user info, redirect to user login
  if (!token || !userInfo) {
    toast.error('Please log in to access your wallet.');
    return <Navigate to="/user/login" replace />;
  }

  // If authenticated, render the child routes
  return <Outlet />;
};

export const AdminProtectedRoute = () => {
  const token = Cookies.get('token');
  const adminInfo = Cookies.get('adminInfo');

  // If there's no token or no admin info, redirect to admin login
  if (!token || !adminInfo) {
    toast.error('Unauthorized. Merchant access only.');
    return <Navigate to="/admin/login" replace />;
  }

  // If authenticated, render the child routes
  return <Outlet />;
};
